/// Performs a stable merge sort on a slice of elements.
///
/// This function allocates a new `Vec<T>` containing the sorted elements.
/// It uses a classic divide-and-conquer approach with a temporary buffer.
///
/// # Complexity
/// - Time: O(n log n) in all cases (best, average, and worst).
/// - Space: O(n) auxiliary space for the temporary buffer during merging.
///
/// # Type Constraints
/// - `T` must implement `Ord` to allow comparison.
/// - `T` must implement `Clone` to facilitate copying elements into the result.
///
/// # Examples
/// ```
/// let data = vec![5, 2, 9, 1, 5, 6];
/// let sorted = merge_sort::merge_sort(&data);
/// assert_eq!(sorted, vec![1, 2, 5, 5, 6, 9]);
/// ```
pub fn merge_sort<T: Ord + Clone>(v: &[T]) -> Vec<T> {
    if v.len() <= 1 {
        return v.to_vec();
    }

    let mid = v.len() / 2;
    let left = merge_sort(&v[..mid]);
    let right = merge_sort(&v[mid..]);

    merge(&left, &right)
}

/// Merges two sorted slices into a single sorted vector.
///
/// This is a helper function used by `merge_sort`. It assumes both input slices
/// are already sorted and produces a new sorted vector containing all elements.
///
/// # Complexity
/// - Time: O(n + m), where n and m are the lengths of the two input slices.
/// - Space: O(n + m) for the resulting vector.
